// Content with portions generated by generative AI platform
package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.kura.core.testutil.TestUtil;
import org.eclipse.kura.linux.watchdog.WatchdogServiceOptions.WatchdogMode;
import org.eclipse.kura.watchdog.WatchdogStatus;
import org.junit.After;
import org.junit.Test;

public class DeactivationOrderingTest {

    private static final long WAIT_TIMEOUT_MS = 10000;
    private static final long NEGATIVE_WAIT_MS = 300;
    private static final int PING_INTERVAL_MS = 50;
    private static final int OTHER_PING_INTERVAL_MS = 60;

    private final CountDownLatch tickEntered = new CountDownLatch(1);
    private final CountDownLatch releaseTick = new CountDownLatch(1);
    private final CountDownLatch backendDeactivated = new CountDownLatch(1);
    private final AtomicBoolean tickFinished = new AtomicBoolean();
    private final AtomicBoolean tickInterrupted = new AtomicBoolean();
    private final AtomicBoolean tickFinishedBeforeDeactivation = new AtomicBoolean();
    private final AtomicInteger configureCalls = new AtomicInteger();
    private final AtomicInteger configureCallsAtDeactivation = new AtomicInteger(-1);
    private BlockingBackendServiceImpl svc;
    private Thread deactivationThread;

    @Test
    public void tickInFlightFinishesBeforeBackendsAreDeactivated() throws Exception {
        givenActivatedServiceWithTickBlockedInsideBackend();

        whenDeactivationIsStartedOnAnotherThread();

        thenBackendIsNotDeactivatedWhileTickIsBlocked();

        whenTickIsReleased();

        thenBackendIsDeactivatedAfterTickFinished();
        thenTickThreadWasNotInterrupted();
    }

    @Test
    public void updateQueuedBehindBlockedTickIsDiscarded() throws Exception {
        givenActivatedServiceWithTickBlockedInsideBackend();
        givenUpdateWithDifferentConfigurationQueued();

        whenDeactivationIsStartedOnAnotherThread();
        whenExecutorHasBeenShutDown();
        whenTickIsReleased();

        thenBackendIsDeactivatedAfterTickFinished();
        thenBackendWasNotReconfiguredAfterDeactivationStarted();
    }

    @Test
    public void updateAfterDeactivationDoesNotThrow() throws Exception {
        givenActivatedServiceWithTickNotBlocked();
        givenServiceIsDeactivated();

        whenUpdateWithDifferentConfigurationIsReceived();

        thenBackendWasNotReconfiguredAfterDeactivationStarted();
    }

    @Test
    public void deactivatingTwiceDoesNotThrow() throws Exception {
        givenActivatedServiceWithTickNotBlocked();
        givenServiceIsDeactivated();

        whenServiceIsDeactivatedAgain();

        thenBackendIsDeactivatedAfterTickFinished();
    }

    @After
    public void cleanup() throws Exception {
        this.releaseTick.countDown();
        if (this.deactivationThread != null) {
            this.deactivationThread.join(WAIT_TIMEOUT_MS);
        }
        if (this.svc != null) {
            this.svc.deactivate();
        }
    }

    private void givenActivatedServiceWithTickBlockedInsideBackend() throws Exception {
        this.svc = new BlockingBackendServiceImpl(true);
        this.svc.activate(properties(PING_INTERVAL_MS));

        assertTrue(this.tickEntered.await(WAIT_TIMEOUT_MS, TimeUnit.MILLISECONDS));
    }

    private void givenActivatedServiceWithTickNotBlocked() throws Exception {
        this.releaseTick.countDown();
        this.svc = new BlockingBackendServiceImpl(false);
        this.svc.activate(properties(PING_INTERVAL_MS));

        assertTrue(this.tickEntered.await(WAIT_TIMEOUT_MS, TimeUnit.MILLISECONDS));
    }

    private void givenUpdateWithDifferentConfigurationQueued() {
        this.svc.updated(properties(OTHER_PING_INTERVAL_MS));
    }

    private void givenServiceIsDeactivated() {
        this.svc.deactivate();
    }

    private void whenDeactivationIsStartedOnAnotherThread() {
        this.deactivationThread = new Thread(this.svc::deactivate, "test-deactivation");
        this.deactivationThread.start();
    }

    private void whenExecutorHasBeenShutDown() throws Exception {
        final long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(WAIT_TIMEOUT_MS);
        while (System.nanoTime() < deadline) {
            final ScheduledExecutorService executor = (ScheduledExecutorService) TestUtil.getFieldValue(this.svc,
                    "pollExecutor");
            if (executor.isShutdown()) {
                return;
            }
            Thread.sleep(5);
        }
        fail("Executor was not shut down by deactivate()");
    }

    private void whenTickIsReleased() {
        this.releaseTick.countDown();
    }

    private void whenUpdateWithDifferentConfigurationIsReceived() {
        this.svc.updated(properties(OTHER_PING_INTERVAL_MS));
    }

    private void whenServiceIsDeactivatedAgain() {
        this.svc.deactivate();
    }

    private void thenBackendIsNotDeactivatedWhileTickIsBlocked() throws Exception {
        assertFalse(this.backendDeactivated.await(NEGATIVE_WAIT_MS, TimeUnit.MILLISECONDS));
    }

    private void thenBackendIsDeactivatedAfterTickFinished() throws Exception {
        assertTrue(this.backendDeactivated.await(WAIT_TIMEOUT_MS, TimeUnit.MILLISECONDS));
        if (this.deactivationThread != null) {
            this.deactivationThread.join(WAIT_TIMEOUT_MS);
            assertFalse(this.deactivationThread.isAlive());
        }
        assertTrue(this.tickFinishedBeforeDeactivation.get());
    }

    private void thenTickThreadWasNotInterrupted() {
        assertTrue(this.tickFinished.get());
        assertFalse(this.tickInterrupted.get());
    }

    private void thenBackendWasNotReconfiguredAfterDeactivationStarted() {
        assertEquals(1, this.configureCalls.get());
        final int atDeactivation = this.configureCallsAtDeactivation.get();
        assertTrue(atDeactivation == -1 || atDeactivation == 1);
    }

    private static Map<String, Object> properties(final int pingInterval) {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", true);
        properties.put("watchdogMode", "direct");
        properties.put("pingInterval", pingInterval);
        return properties;
    }

    private class BlockingBackendServiceImpl extends HookedWatchdogServiceImpl {

        private final boolean blockTick;

        BlockingBackendServiceImpl(final boolean blockTick) {
            this.blockTick = blockTick;
        }

        @Override
        protected WatchdogBackend createBackend(final WatchdogMode mode) {
            if (mode == WatchdogMode.DIRECT) {
                return new BlockingBackend(this.blockTick);
            }
            return super.createBackend(mode);
        }
    }

    private class BlockingBackend implements WatchdogBackend {

        private final boolean blockTick;
        private final AtomicBoolean firstTick = new AtomicBoolean(true);

        BlockingBackend(final boolean blockTick) {
            this.blockTick = blockTick;
        }

        @Override
        public WatchdogMode getMode() {
            return WatchdogMode.DIRECT;
        }

        @Override
        public boolean configure(WatchdogServiceOptions options, Optional<WatchdogStatus> failedBackendStatus) {
            DeactivationOrderingTest.this.configureCalls.incrementAndGet();
            return true;
        }

        @Override
        public TickResult onTick(Optional<String> failedCriticalComponent) {
            if (this.firstTick.getAndSet(false)) {
                DeactivationOrderingTest.this.tickEntered.countDown();
                if (this.blockTick) {
                    try {
                        DeactivationOrderingTest.this.releaseTick.await(WAIT_TIMEOUT_MS, TimeUnit.MILLISECONDS);
                    } catch (InterruptedException e) {
                        DeactivationOrderingTest.this.tickInterrupted.set(true);
                    }
                    if (Thread.currentThread().isInterrupted()) {
                        DeactivationOrderingTest.this.tickInterrupted.set(true);
                    }
                }
                DeactivationOrderingTest.this.tickFinished.set(true);
            }
            return TickResult.unchanged();
        }

        @Override
        public void deactivate() {
            DeactivationOrderingTest.this.tickFinishedBeforeDeactivation
                    .set(DeactivationOrderingTest.this.tickFinished.get());
            DeactivationOrderingTest.this.configureCallsAtDeactivation
                    .compareAndSet(-1, DeactivationOrderingTest.this.configureCalls.get());
            DeactivationOrderingTest.this.backendDeactivated.countDown();
        }

        @Override
        public int getHardwareTimeout() {
            return 0;
        }

        @Override
        public WatchdogStatus getStatus() {
            return WatchdogStatus.builder().build();
        }
    }
}
